insert into public.item_options select * from jsonb_populate_recordset(null::public.item_options,'[{"id": "02daa9f8-c21f-5930-b366-b33648f63116", "item_id": "2c482a28-27ed-51f9-9d4f-e9cc28a6e163", "content_en": null, "content_hy": "Բնորոշ արագությունը մեծանում է։", "option_key": "A", "display_order": 1}, {"id": "9e27566c-acc8-5e46-9cb0-66caafffefb2", "item_id": "2c482a28-27ed-51f9-9d4f-e9cc28a6e163", "content_en": null, "content_hy": "Բնորոշ արագությունը փոքրանում է։", "option_key": "B", "display_order": 2}, {"id": "7b965caa-67d3-509f-9554-37e40561aa54", "item_id": "2c482a28-27ed-51f9-9d4f-e9cc28a6e163", "content_en": null, "content_hy": "Բնորոշ արագությունը մնում է անփոփոխ։", "option_key": "C", "display_order": 3}, {"id": "a8245250-9b6d-5160-a087-6e1ef96a731f", "item_id": "2c482a28-27ed-51f9-9d4f-e9cc28a6e163", "content_en": null, "content_hy": "Անկանոն շարժումը փոխարինվում է բոլոր մասնիկների՝ նույն ուղղությամբ շարժմամբ։", "option_key": "D", "display_order": 4}, {"id": "0aee0ed0-f996-5752-a240-e482b41e5583", "item_id": "d17eb596-b688-5367-9f5c-0bda451dbee8", "content_en": null, "content_hy": "20 °C-ում դիֆուզիան ավելի արագ է, քանի որ մասնիկները ցածր ջերմաստիճանում ավելի արագ են շարժվում։", "option_key": "A", "display_order": 1}, {"id": "4ba870bf-856d-5de1-abcf-4f00c9c28624", "item_id": "d17eb596-b688-5367-9f5c-0bda451dbee8", "content_en": null, "content_hy": "40 °C-ում դիֆուզիան ավելի արագ է, քանի որ մասնիկների ջերմային շարժումն ավելի արագ է։", "option_key": "B", "display_order": 2}, {"id": "1d74f670-5659-5fe9-909f-26e7ee3dd5ca", "item_id": "d17eb596-b688-5367-9f5c-0bda451dbee8", "content_en": null, "content_hy": "Երկու անոթներում դիֆուզիան նույն արագությունն ունի, քանի որ ջերմաստիճանը չի ազդում մասնիկների շարժման վրա։", "option_key": "C", "display_order": 3}, {"id": "fa7cd822-b754-5ad9-9f14-7356e8beee3d", "item_id": "d17eb596-b688-5367-9f5c-0bda451dbee8", "content_en": null, "content_hy": "Ոչ մի անոթում դիֆուզիա չի լինի, քանի դեռ հեղուկներն արտաքինից չեն խառնել։", "option_key": "D", "display_order": 4}, {"id": "a783360f-5f3f-5516-887f-9e56bbb5603b", "item_id": "e6e17a09-f696-51d9-bd3b-14b8b7197de5", "content_en": null, "content_hy": "Մոլեկուլները չեն շարժվում, քանի որ ջերմաստիճանը զրո է։", "option_key": "A", "display_order": 1}, {"id": "acf5dea0-179f-53b5-b707-ac188cb2759b", "item_id": "e6e17a09-f696-51d9-bd3b-14b8b7197de5", "content_en": null, "content_hy": "Ջերմային շարժումը կսկսվի միայն այն ժամանակ, երբ ջերմաստիճանը բարձրանա 0 °C-ից։", "option_key": "B", "display_order": 2}, {"id": "89a7c7cf-c74c-5fbb-bfb3-9ea191c878d5", "item_id": "e6e17a09-f696-51d9-bd3b-14b8b7197de5", "content_en": null, "content_hy": "0 °C-ում մոլեկուլները շարունակում են անկանոն ջերմային շարժումը։", "option_key": "C", "display_order": 3}, {"id": "1bac23a2-549a-5035-b5c7-31c0d4424fa7", "item_id": "e6e17a09-f696-51d9-bd3b-14b8b7197de5", "content_en": null, "content_hy": "0 °C-ում բոլոր մոլեկուլները շարժվում են նույն ուղղությամբ։", "option_key": "D", "display_order": 4}, {"id": "a2c61156-d5cc-5a06-bf99-aa7855cf67bb", "item_id": "e778fc3a-f05d-534d-920c-0fede1df8844", "content_en": null, "content_hy": "Եզրակացությունը ճիշտ է. ավելի արագ մոլեկուլներ ունեցող գազը միշտ ավելի տաք է՝ անկախ նյութի տեսակից։", "option_key": "A", "display_order": 1}, {"id": "00cb9ad5-5426-5512-a312-e4be69714bbb", "item_id": "e778fc3a-f05d-534d-920c-0fede1df8844", "content_en": null, "content_hy": "Եզրակացությունը սխալ է. թթվածինն է ավելի տաք, քանի որ նրա մոլեկուլներն ավելի դանդաղ են շարժվում։", "option_key": "B", "display_order": 2}, {"id": "7c878482-34fd-59a5-9ca1-af3e9bb2ccd7", "item_id": "e778fc3a-f05d-534d-920c-0fede1df8844", "content_en": null, "content_hy": "Տվյալներից մեկը սխալ է. նույն ջերմաստիճանում բոլոր նյութերի մոլեկուլները պարտադիր նույն բնորոշ արագությունն ունեն։", "option_key": "C", "display_order": 3}, {"id": "a198333b-cd3c-517e-aa97-972636842a50", "item_id": "e778fc3a-f05d-534d-920c-0fede1df8844", "content_en": null, "content_hy": "Եզրակացությունը սխալ է. երկու գազերի ջերմաստիճանը նույնն է, թեև տարբեր նյութերի մոլեկուլների բնորոշ արագությունները տարբեր են։", "option_key": "D", "display_order": 4}]'::jsonb);
