insert into public.misconceptions select * from jsonb_populate_recordset(null::public.misconceptions,'[{"id": "47f71e91-0d93-5c3c-90eb-f0974dc5332e", "code": "diffusion_requires_stirring", "status": "active", "skill_id": "8581be3b-907c-5105-a253-aaf03828bc07", "title_hy": "Դիֆուզիայի համար արտաքին խառնում է անհրաժեշտ", "created_at": "2026-10-05T08:30:17.903344+00:00", "updated_at": "2026-10-05T18:02:08.816394+00:00", "description_hy": "Մասնիկների անկանոն շարժմամբ պայմանավորված ինքնաբերական խառնումը շփոթվում է արտաքին խառնելու հետ։"}, {"id": "0082ab87-7e08-5e75-9227-ecec8853c945", "code": "equal_temperature_implies_equal_speed", "status": "active", "skill_id": "8581be3b-907c-5105-a253-aaf03828bc07", "title_hy": "Նույն ջերմաստիճանում տարբեր նյութերի մասնիկներն ունեն նույն բնորոշ արագությունը", "created_at": "2026-10-05T08:30:17.903344+00:00", "updated_at": "2026-10-05T18:02:44.825564+00:00", "description_hy": "Ջերմաստիճանների հավասարությունը շփոթվում է տարբեր նյութերի մոլեկուլների բնորոշ արագությունների հավասարության հետ։"}, {"id": "c494dea7-de89-5918-a20e-077cd2be226f", "code": "heating_slows_motion", "status": "active", "skill_id": "8581be3b-907c-5105-a253-aaf03828bc07", "title_hy": "Տաքացնելիս մասնիկների շարժումը դանդաղում է", "created_at": "2026-10-05T08:30:17.903344+00:00", "updated_at": "2026-10-05T18:03:01.77158+00:00", "description_hy": "Նույն նյութի ջերմաստիճանի բարձրացման և ջերմային շարժման արագության կապը մեկնաբանվում է հակառակ ուղղությամբ։"}, {"id": "d6ce54ff-3d29-5484-9cac-26f3d12a6655", "code": "temperature_effect_on_diffusion_reversed", "status": "active", "skill_id": "8581be3b-907c-5105-a253-aaf03828bc07", "title_hy": "Ցածր ջերմաստիճանում դիֆուզիան ավելի արագ է", "created_at": "2026-10-05T08:30:17.903344+00:00", "updated_at": "2026-10-05T18:03:16.003729+00:00", "description_hy": "Ջերմաստիճանի ազդեցությունը մասնիկների շարժման և դիֆուզիայի վրա մեկնաբանվում է հակառակ ուղղությամբ։"}, {"id": "80611473-d889-523a-b2c2-dea4bb76adff", "code": "temperature_unrelated_to_motion", "status": "active", "skill_id": "8581be3b-907c-5105-a253-aaf03828bc07", "title_hy": "Ջերմաստիճանը չի ազդում մասնիկների շարժման վրա", "created_at": "2026-10-05T08:30:17.903344+00:00", "updated_at": "2026-10-05T18:03:30.037281+00:00", "description_hy": "Նույն նյութի ջերմաստիճանի փոփոխությունը չի կապվում մասնիկների շարժման բնորոշ արագության փոփոխության հետ։"}, {"id": "4d952a63-30e9-5eec-8dbf-a349a79b79f5", "code": "thermal_motion_is_directed", "status": "active", "skill_id": "8581be3b-907c-5105-a253-aaf03828bc07", "title_hy": "Ջերմային շարժումը բոլոր մասնիկների նույն ուղղությամբ շարժումն է", "created_at": "2026-10-05T08:30:17.903344+00:00", "updated_at": "2026-10-05T18:04:15.081489+00:00", "description_hy": "Մասնիկների անկանոն ջերմային շարժումը շփոթվում է ուղղորդված ընդհանուր շարժման հետ։"}, {"id": "f251b717-a51e-5a46-aece-fad4c365eb34", "code": "zero_celsius_stops_motion", "status": "active", "skill_id": "8581be3b-907c-5105-a253-aaf03828bc07", "title_hy": "0 °C-ում մասնիկների ջերմային շարժումը դադարում է", "created_at": "2026-10-05T08:30:17.903344+00:00", "updated_at": "2026-10-05T18:04:28.48124+00:00", "description_hy": "Ցելսիուսի սանդղակի զրոն սխալմամբ ընդունվում է որպես մոլեկուլների ջերմային շարժման բացակայություն։"}, {"id": "3dc326f9-f240-5b97-8cd4-8c6c76bf460a", "code": "different_substances_speed_orders_temperature", "status": "active", "skill_id": "8581be3b-907c-5105-a253-aaf03828bc07", "title_hy": "Տարբեր նյութերի ջերմաստիճանները որոշվում են միայն մոլեկուլների արագությամբ", "created_at": "2026-10-05T08:30:17.903344+00:00", "updated_at": "2026-10-05T18:01:51.973603+00:00", "description_hy": "Նույն նյութի համար կիրառվող համեմատությունը առանց հիմնավորման տարածվում է տարբեր նյութերի վրա՝ անտեսելով տրված ջերմաստիճանները։"}]'::jsonb);
