"}, "status": "draft", "skill_id": "8581be3b-907c-5105-a253-aaf03828bc07", "stimulus": {}, "item_type": "single_choice", "prompt_en": null, "prompt_hy": "Դասագրքի տվյալներով՝ 0 °C-ում ջրածնի մոլեկուլների ջերմային շարժման բնորոշ արագությունը մոտ 1800 մ/վ է, իսկ թթվածնինը՝ 450 մ/վ։ Սովորողը եզրակացնում է. «Ջրածինն ավելի տաք է, քանի որ նրա մոլեկուլներն ավելի արագ են շարժվում»։ Ո՞ր գնահատականն է հիմնավորված։", "created_at": "2026-10-05T08:30:17.903344+00:00", "difficulty": 3, "retired_at": null, "updated_at": "2026-10-05T08:30:17.903344+00:00", "version_no": 1, "item_family": "temperature_particle_motion", "variant_key": "temperature_particle_motion:04", "variant_seed": null, "review_status": "needs_review", "retired_reason": null, "difficulty_band": "core", "item_template_id": "c4ce01f1-3c7d-5b18-805d-4f4ae8d9d72a", "last_reviewed_at": null, "last_reviewed_by": null, "source_reference": "Գործող Ֆիզիկա 7 ծրագիր՝ Թեմա 2, պարտադիր վերջնարդյունք 1(5); Ֆիզիկա 7 (2023), Գլուխ II, §10, տպագիր էջ 32; §11, տպագիր էջեր 33-35", "validation_state": "provisional_no_sme_review", "variant_parameters": {"focusKey": "cross_substance_inference", "authoredCatalog": true, "evidencePurpose": "transfer_reasoning"}, "replacement_item_id": null, "variant_fingerprint": "82a46cc24ba849e7bb4f91a613f22b60"}, "options": [{"id": "a2c61156-d5cc-5a06-bf99-aa7855cf67bb", "item_id": "e778fc3a-f05d-534d-920c-0fede1df8844", "content_en": null, "content_hy": "Եզրակացությունը ճիշտ է. ավելի արագ մոլեկուլներ ունեցող գազը միշտ ավելի տաք է՝ անկախ նյութի տեսակից։", "option_key": "A", "display_order": 1}, {"id": "00cb9ad5-5426-5512-a312-e4be69714bbb", "item_id": "e778fc3a-f05d-534d-920c-0fede1df8844", "content_en": null, "content_hy": "Եզրակացությունը սխալ է. թթվածինն է ավելի տաք, քանի որ նրա մոլեկուլներն ավելի դանդաղ են շարժվում։", "option_key": "B", "display_order": 2}, {"id": "7c878482-34fd-59a5-9ca1-af3e9bb2ccd7", "item_id": "e778fc3a-f05d-534d-920c-0fede1df8844", "content_en": null, "content_hy": "Տվյալներից մեկը սխալ է. նույն ջերմաստիճանում բոլոր նյութերի մոլեկուլները պարտադիր նույն բնորոշ արագությունն ունեն։", "option_key": "C", "display_order": 3}, {"id": "a198333b-cd3c-517e-aa97-972636842a50", "item_id": "e778fc3a-f05d-534d-920c-0fede1df8844", "content_en": null, "content_hy": "Եզրակացությունը սխալ է. երկու գազերի ջերմաստիճանը նույնն է, թեև տարբեր նյութերի մոլեկուլների բնորոշ արագությունները տարբեր են։", "option_key": "D", "display_order": 4}], "answerKey": {"answer": "D", "item_id": "e778fc3a-f05d-534d-920c-0fede1df8844", "tolerance": null, "updated_at": "2026-10-05T08:30:17.903344+00:00", "feedback_code": "temperature_particle_motion", "accepted_units": [], "canonical_unit": null}, "misconceptions": [{"code": "different_substances_speed_orders_temperature", "mappingNote": "Նույն նյութի համար կիրառվող համեմատությունը առանց հիմնավորման տարածվում է տարբեր նյութերի վրա՝ անտեսելով տրված ջերմաստիճանները։", "responseKey": "A"}, {"code": "different_substances_speed_orders_temperature", "mappingNote": "Նույն նյութի համար կիրառվող համեմատությունը առանց հիմնավորման տարածվում է տարբեր նյութերի վրա՝ անտեսելով տրված ջերմաստիճանները։", "responseKey": "B"}, {"code": "equal_temperature_implies_equal_speed", "mappingNote": "Ջերմաստիճանների հավասարությունը շփոթվում է տարբեր նյութերի մոլեկուլների բնորոշ արագությունների հավասարության հետ։", "responseKey": "C"}]}, "created_at": "2026-10-05T08:30:17.903344+00:00", "created_by": null, "version_no": 1, "change_summary": "15B.9 հեռանկարային ապացուցողական սխեմայով յոթերորդ կառավարվող սևագիր ընտանիքի ստեղծում"}]'::jsonb);
