insert into public.item_template_remediation_guides select * from jsonb_populate_recordset(null::public.item_template_remediation_guides,'[{"id": "995f10bd-76af-5994-9942-2711892faa75", "status": "published", "metadata": {"sprint": "15B.9", "learnerVisible": false, "referenceMetadata": {"textbookSha256": "d8404d572f145d4afe924d0b8af900b3d9ed085a37893594667ab07a2ec12904", "textbookLocator": "Ֆիզիկա 7 (2023), Գլուխ II, §10, տպագիր էջ 32; §11, տպագիր էջեր 33-35", "programmeOutcomeLocator": "7-րդ դասարան / Թեմա 2 / Վերջնարդյունքներ / Պարտադիր 1(5)"}, "authoringProfileVersion": "haiedu-evidence-blueprint-v1"}, "title_hy": "Ինչպե՞ս կապել ջերմաստիճանը մասնիկների շարժման հետ", "hint_1_hy": "Նույն նյութի ջերմաստիճանի բարձրացումը կապի՛ր նրա մասնիկների անկանոն շարժման արագության մեծացման հետ։", "hint_2_hy": "0 °C ջերմաստիճանում մասնիկների ջերմային շարժումը չի դադարում։ Տարբեր գազերի դեպքում միևնույն ջերմաստիճանը դեռևս չի նշանակում, որ դրանց մոլեկուլներն ունեն շարժման միևնույն արագությունը։", "created_at": "2026-10-05T08:30:17.903344+00:00", "updated_at": "2026-10-05T10:26:10.304211+00:00", "strategy_hy": "Նախ հստակեցրու՝ նույն նյո՞ւթն ես համեմատում, թե՞ տարբեր նյութեր։ \nԵթե նյութը նույնն է, ապա ջերմաստիճանը բարձրացնելիս նրա մասնիկների անկանոն, քաոսային շարժման արագությունը մեծանում է։ Բայց դա չի նշանակում, թե բոլոր մասնիկներն ամեն պահի սկսում են շարժվել նույն արագությամբ, կամ նրանց շարժումը դառնում է ուղղորդված։ Հենց այս օրինաչափությունն էլ օգնում է հասկանալ, թե ինչու է ջերմաստիճանի բարձրացմանը զուգընթաց դիֆուզիան ավելի արագ ընթանում։ Ընդ որում, մի՛ մոռացիր, որ **0 °C** ջերմաստիճանում մասնիկների շարժումը կանգ չի առնում։ \nԻսկ երբ համեմատում ես տարբեր նյութեր, հիմնվիր տրված ջերմաստիճանների վրա և միանգամից մի՛ ենթադրիր, թե ավելի արագ մոլեկուլներ ունեցող նյութն անպայման ավելի տաք է։", "guide_version": 2, "item_template_id": "c4ce01f1-3c7d-5b18-805d-4f4ae8d9d72a", "worked_example_hy": "Օրինակ՝ դասագրքում թթվածնի մոլեկուլների ջերմային շարժման բնորոշ արագությունը 0 °C-ում մոտ 450 մ/վ է, իսկ 200 °C-ում՝ 585 մ/վ։ Նույն գազի օրինակով տեսնում ենք, որ ավելի բարձր ջերմաստիճանին համապատասխանում է մասնիկների շարժման ավելի մեծ արագություն։ Սակայն նկատի՛ր, որ այս թվերից արագության և ջերմաստիճանի միջև ուղիղ համեմատական կապ չի բխում։", "trigger_error_code": null, "allowed_parameter_keys": []}]'::jsonb);
